-- Most graph workloads are this, and Postgres handles it.
-- Trade-off: you pay read-time join cost, you keep standard ops.
CREATE TABLE person (id BIGINT PRIMARY KEY, name TEXT);
CREATE TABLE friendship (user_a BIGINT REFERENCES person(id), user_b BIGINT REFERENCES person(id), PRIMARY KEY (user_a, user_b));
CREATE INDEX ON friendship (user_b, user_a);

-- Friends of friends, bounded to 2 hops, paginated, timeout-safe:
SELECT DISTINCT f2.user_b AS fof
FROM friendship f1
JOIN friendship f2 ON f2.user_a = f1.user_b
WHERE f1.user_a = $1
  AND f2.user_b <> $1
LIMIT 100;

-- Arbitrary depth without a graph DB:
WITH RECURSIVE reach(depth, node) AS (
  SELECT 1, user_b FROM friendship WHERE user_a = $1
  UNION
  SELECT r.depth + 1, f.user_b
  FROM reach r JOIN friendship f ON f.user_a = r.node
  WHERE r.depth < 4
) SELECT DISTINCT node FROM reach LIMIT 500;
